    { const char * tb_v1516 = "    tb_rand_state ^= tb_rand_state << 13; tb_rand_state ^= tb_rand_state >> 7; tb_rand_state ^= tb_rand_state << 17;\n"; *(const char * *)tb_grow(v_lines) = tb_v1516; }
