    { const char * tb_v1550 = "//   0 — таблица slots с хешем (текст или разбросанные числа) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v1550; }
    { const char * tb_v1551 = "typedef struct {\n"; *(const char * *)tb_grow(v_lines) = tb_v1551; }
