    { const char * tb_v1595 = "static void tb_dreindex(tb_dict *d, long long nslots) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1595; }
    { const char * tb_v1596 = "    d->mode = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1596; }
